function buildProjectFinancialSummary_(projects){const normalized=(projects||[]).map(p=>{const expenses=Number(p['التكلفة الفعلية']||0),clientValue=Number(p['قيمة العميل']||0),receipts=Number(p['التحصيلات']||0)-Number(p['المردودات']||0),percentageDue=Math.max(0,clientValue-expenses-Number(p['قيمة التصميم']||0)-Number(p['الأعمال الإضافية']||0)+Number(p['الاستقطاعات']||0)),availableClientFunds=receipts-expenses,outstanding=clientValue-receipts;return {raw:p,expenses,clientValue,receipts,percentageDue,availableClientFunds,outstanding}}),archivedStatus=new Set(['ARCHIVED','CLOSED','COMPLETED','CANCELLED','مؤرشف','منتهي','مغلق','ملغي']),active=normalized.filter(x=>!archivedStatus.has(String(x.raw['الحالة التشغيلية']||'').trim().toUpperCase())),archived=normalized.filter(x=>!active.includes(x)),totals=active.reduce((t,p)=>(t.expenses+=p.expenses,t.clientValue+=p.clientValue,t.receipts+=p.receipts,t.percentageDue+=p.percentageDue,t.availableClientFunds+=p.availableClientFunds,t.outstanding+=p.outstanding,t),{expenses:0,clientValue:0,receipts:0,percentageDue:0,availableClientFunds:0,outstanding:0});return {active:active.map(x=>Object.assign({},x.raw,x)),archived:archived.map(x=>Object.assign({},x.raw,x)),totals}}
async function loadLeadershipProjectSummary_(){if(!['SUPER_ADMIN','ADMIN','PARTNER','FINANCIAL_MANAGER'].includes(String(state.profile?.role||'')))return;const r=await api('view.load',{view:'projects'});if(!r?.ok||!r.data?.projects)return;state.data.projectFinancialSummary=buildProjectFinancialSummary_(r.data.projects);render()}
