const approvalsOriginal=approvals;
approvals=function(){const notices=(state.data.notifications||[]).filter(x=>x['مقروء']!==true);return `${approvalsOriginal()}${notices.length?`<div class="panel"><h2>${state.lang==='ar'?'الإشعارات والتنبيهات':'Notifications & alerts'}</h2>${notices.map(n=>`<p><b>${esc(state.lang==='ar'?n['العنوان العربي']:n['العنوان الإنجليزي'])}</b> — ${esc(state.lang==='ar'?n['النص العربي']:n['النص الإنجليزي'])}</p>`).join('')}</div>`:''}`};
function notificationCards(){const notices=(state.data.notifications||[]).filter(x=>!isTrue_(x['مقروء']));if(!notices.length)return '';return `<div class="panel"><div class="section-heading"><h2>${state.lang==='ar'?'الإشعارات المطلوبة':'Required notifications'}</h2><div class="actions"><button id="enableDeviceNotifications" class="secondary" type="button">${state.lang==='ar'?'تفعيل إشعارات هذا الجهاز':'Enable device notifications'}</button><button id="readAllNotifications" class="secondary" type="button">${state.lang==='ar'?'تحديد الكل كمقروء':'Mark all read'}</button></div></div>${notices.map(n=>`<div class="notice-row"><b>${esc(state.lang==='ar'?n['العنوان العربي']:n['العنوان الإنجليزي'])}</b><span>${esc(state.lang==='ar'?n['النص العربي']:n['النص الإنجليزي'])}</span><button class="notification-read secondary" data-id="${esc(n['معرف الإشعار'])}" type="button">${state.lang==='ar'?'تمت المراجعة':'Reviewed'}</button></div>`).join('')}</div>`}
dash=function(){return `${dashOriginal()}${notificationCards()}`};
