function bankReviewCards(){const rows=state.data.bankStatements||[];if(!rows.length)return `<div class="empty">${t('none')}</div>`;return rows.map(x=>`<div class="panel"><b>${esc(x['البنك']||'')}</b> — ${esc(x['من تاريخ']||'')} / ${esc(x['إلى تاريخ']||'')}<br><span>${state.lang==='ar'?'الفرق':'Difference'}: ${money(x['الفرق'])} — ${esc(x['الحالة']||'')}</span>${canAction('finance','approve')&&['UNDER_REVIEW','RECONCILED'].includes(x['الحالة'])?`<div class="actions"><button class="bank-review primary" data-id="${esc(x['معرف الكشف'])}" data-version="${esc(x['الإصدار'])}" data-decision="APPROVE">${t('approve')}</button><button class="bank-review secondary" data-id="${esc(x['معرف الكشف'])}" data-version="${esc(x['الإصدار'])}" data-decision="REJECT">${t('reject')}</button></div>`:''}</div>`).join('')}
const financeSmartOriginalV36=financeSmart;
financeSmart=function(){return `${financeSmartOriginalV36()}<div class="panel"><h2>${state.lang==='ar'?'مراجعة واعتماد كشوف البنك':'Review and approve bank statements'}</h2>${bankReviewCards()}</div>`};

function financialStatementsPanel(){const f=state.data.financialStatements;return `<div class="panel"><h2>${state.lang==='ar'?'القوائم المالية والتوقعات':'Financial statements and forecast'}</h2><div class="form-grid"><label class="field">${state.lang==='ar'?'من تاريخ':'From'}<input id="financialFrom" type="date"></label><label class="field">${state.lang==='ar'?'إلى تاريخ':'To'}<input id="financialTo" type="date"></label></div><div class="actions"><button id="loadFinancialStatements" class="primary" type="button">${state.lang==='ar'?'إعداد القوائم':'Build statements'}</button><button id="printFinancialStatements" class="secondary" type="button">PDF / ${state.lang==='ar'?'طباعة':'Print'}</button></div></div>${f?`<div class="cards"><div class="card"><b>${state.lang==='ar'?'الإيرادات':'Revenue'}</b><strong>${money(f.incomeStatement.revenue)}</strong></div><div class="card"><b>${state.lang==='ar'?'المصروفات':'Expenses'}</b><strong>${money(f.incomeStatement.expenses)}</strong></div><div class="card"><b>${state.lang==='ar'?'صافي الربح':'Net profit'}</b><strong>${money(f.incomeStatement.netProfit)}</strong></div><div class="card"><b>${state.lang==='ar'?'فرق توازن المركز المالي':'Balance check'}</b><strong>${money(f.financialPosition.balanceCheck)}</strong></div><div class="card"><b>${state.lang==='ar'?'ضريبة المدخلات القابلة للخصم':'Recoverable input VAT'}</b><strong>${money(f.taxSummary.inputVat)}</strong></div><div class="card"><b>${state.lang==='ar'?'ضريبة المخرجات':'Output VAT'}</b><strong>${money(f.taxSummary.outputVat)}</strong></div><div class="card"><b>${state.lang==='ar'?'صافي الضريبة المستحقة':'Net VAT payable'}</b><strong>${money(f.taxSummary.netVatPayable)}</strong></div></div><div class="panel"><h2>${state.lang==='ar'?'ميزان المراجعة':'Trial balance'}</h2>${table(f.trialBalance)}</div><div class="panel"><h2>${state.lang==='ar'?'التدفقات النقدية':'Cash flow'}</h2>${table(f.cashFlow.monthly)}</div><div class="panel"><h2>${state.lang==='ar'?'توقع ثلاثة أشهر «تقديري»':'Three-month forecast (estimate)'}</h2>${table(f.forecast.nextThreeMonths)}</div>`:''}`}
const reportsOriginalV36=reports;
reports=function(){return `${reportsOriginalV36()}${financialStatementsPanel()}`};

const notificationSettingsLoad=load;
load=async function(){await notificationSettingsLoad();if(state.view==='settings'&&canAction('settings','view'))await list('systemUsers','المستخدمون','settings')};
function notificationPreferencesPanel(){const users=state.data.systemUsers||[],selected=users.find(x=>String(x['معرف المستخدم'])===String(state.profile.userId))||users[0]||{},level=selected['مستوى الإشعارات']||'ALL';return `<div class="panel"><h2>${state.lang==='ar'?'إعدادات الإشعارات حسب المستخدم':'Notification settings by user'}</h2><p>${state.lang==='ar'?'نوع الإشعار نفسه يظل مقيدًا بصلاحيات المستخدم الأساسية؛ هذه الخيارات تتحكم فقط في قناة الإرسال ومستوى الأهمية.':'Notification content remains restricted by the user’s core permissions; these options only control channel and severity.'}</p><form id="notificationPreferences"><div class="form-grid"><label class="field">${state.lang==='ar'?'المستخدم':'User'}<select name="userId">${users.map(x=>`<option value="${esc(x['معرف المستخدم'])}" ${String(x['معرف المستخدم'])===String(selected['معرف المستخدم'])?'selected':''}>${esc(x['البريد'])} — ${esc(x['الدور'])}</option>`).join('')}</select></label><label class="check-line"><input name="inApp" type="checkbox" ${selected['إشعارات داخل التطبيق']===''||selected['إشعارات داخل التطبيق']==null||isTrue_(selected['إشعارات داخل التطبيق'])?'checked':''}><span>${state.lang==='ar'?'داخل التطبيق':'In app'}</span></label><label class="check-line"><input name="email" type="checkbox" ${selected['إشعارات البريد']===''||selected['إشعارات البريد']==null||isTrue_(selected['إشعارات البريد'])?'checked':''}><span>${state.lang==='ar'?'البريد الإلكتروني':'Email'}</span></label><label class="field">${state.lang==='ar'?'مستوى الإشعارات':'Notification level'}<select name="level"><option value="ALL" ${level==='ALL'?'selected':''}>${state.lang==='ar'?'جميع المسموح به':'All permitted'}</option><option value="HIGH_ONLY" ${level==='HIGH_ONLY'?'selected':''}>${state.lang==='ar'?'المهم والعاجل فقط':'High and critical only'}</option><option value="CRITICAL_ONLY" ${level==='CRITICAL_ONLY'?'selected':''}>${state.lang==='ar'?'العاجل فقط':'Critical only'}</option></select></label></div><button class="primary">${t('save')}</button></form></div>`}
const settingsOriginalV37=settings;
function permissionManagementPanel(){const users=(state.data.systemUsers||[]).filter(x=>!isTrue_(x['حساب محمي'])),modules=['dashboard','approvals','transactions','projects','clients','parties','employees','payroll','loans','finance','agreements','assets','audit','reports','settings'],actions=['view','create','edit','submit','approve','reject','post','reverse','export','print'];return `<div class="panel"><h2>${state.lang==='ar'?'زيادة أو تقليل صلاحية مستخدم':'Grant or reduce a user permission'}</h2><form id="permissionForm"><div class="form-grid"><label class="field">${state.lang==='ar'?'المستخدم':'User'}<select name="userId" required><option value=""></option>${users.map(x=>`<option value="${esc(x['معرف المستخدم'])}">${esc(x['البريد'])} — ${esc(x['الدور'])}</option>`).join('')}</select></label><label class="field">${state.lang==='ar'?'الوحدة':'Module'}<select name="module" required>${modules.map(x=>`<option value="${x}">${x}</option>`).join('')}</select></label><label class="field">${state.lang==='ar'?'الإجراء':'Action'}<select name="permissionAction" required>${actions.map(x=>`<option value="${x}">${x}</option>`).join('')}</select></label><label class="field">${state.lang==='ar'?'القرار':'Decision'}<select name="status"><option value="ALLOW">${state.lang==='ar'?'سماح':'Allow'}</option><option value="DENY">${state.lang==='ar'?'منع':'Deny'}</option></select></label><label class="field">${state.lang==='ar'?'حتى تاريخ «اختياري»':'Until (optional)'}<input name="toDate" type="date"></label><label class="field">${state.lang==='ar'?'السبب':'Reason'}<input name="reason" required></label></div><button class="primary">${t('save')}</button></form></div>`}
settings=function(){return `${settingsOriginalV37()}${notificationPreferencesPanel()}${permissionManagementPanel()}`};

document.addEventListener('change',e=>{if(e.target.form?.id!=='notificationPreferences'||e.target.name!=='userId')return;const u=(state.data.systemUsers||[]).find(x=>String(x['معرف المستخدم'])===String(e.target.value)),f=e.target.form;if(!u)return;f.inApp.checked=u['إشعارات داخل التطبيق']===''||u['إشعارات داخل التطبيق']==null||isTrue_(u['إشعارات داخل التطبيق']);f.email.checked=u['إشعارات البريد']===''||u['إشعارات البريد']==null||isTrue_(u['إشعارات البريد']);f.level.value=u['مستوى الإشعارات']||'ALL'});
document.addEventListener('submit',async e=>{if(e.target.id!=='notificationPreferences')return;e.preventDefault();e.stopImmediatePropagation();const f=e.target;await run('notification.preferences.update',{userId:f.userId.value,inApp:f.inApp.checked,email:f.email.checked,level:f.level.value})},true);
document.addEventListener('submit',async e=>{if(e.target.id!=='permissionForm')return;e.preventDefault();e.stopImmediatePropagation();await run('permission.set',obj(e.target))},true);

document.addEventListener('click',async e=>{try{
  if(e.target.classList.contains('notification-read'))await run('notification.read',{id:e.target.dataset.id});
  if(e.target.id==='readAllNotifications')await run('notification.readAll',{});
  if(e.target.id==='enableDeviceNotifications'&&'Notification'in window){const permission=await Notification.requestPermission();if(permission==='granted')new Notification('FOOZIX Live',{body:state.lang==='ar'?'تم تفعيل إشعارات هذا الجهاز':'Device notifications enabled'})}
  if(e.target.classList.contains('bank-review'))await run('bank.statement.review',{id:e.target.dataset.id,version:Number(e.target.dataset.version||1),decision:e.target.dataset.decision,notes:''});
  if(e.target.id==='loadFinancialStatements'){const r=await api('finance.statements',{fromDate:document.querySelector('#financialFrom').value,toDate:document.querySelector('#financialTo').value});if(!r.ok)throw new Error(msg(r));state.data.financialStatements=r.data;render()}
  if(e.target.id==='printFinancialStatements')window.print();
}catch(error){fail(error)}},true);
const legacyMultiRequestLoad=load;
load=async function(){const r=await api('view.load',{view:state.view});if(r&&r.ok){Object.assign(state.data,r.data||{});return}await legacyMultiRequestLoad()};
function capabilityRow(){return `<div class="capability-row"><label class="field">${state.lang==='ar'?'بند العمل':'Work item'}<select name="capabilityItem">${txOptions(state.data.finishItems||[],'معرف البند')}</select></label><label class="field">${state.lang==='ar'?'نوع التعامل':'Supply type'}<select name="capabilityType"><option>مصنعيات</option><option>مشتريات</option><option>شامل</option></select></label><button class="secondary remove-capability" type="button">×</button></div>`}
partyForm=function(){return `<form id="smartMaster" data-entity="party" class="panel"><h2>${state.lang==='ar'?'إضافة مورد أو مقاول':'Add supplier or contractor'}</h2><div class="form-grid"><label class="field">${state.lang==='ar'?'النوع':'Type'}<select name="النوع"><option value="مورد">${state.lang==='ar'?'مورد':'Supplier'}</option><option value="مقاول">${state.lang==='ar'?'مقاول':'Contractor'}</option><option value="مورد ومقاول">${state.lang==='ar'?'مورد ومقاول':'Both'}</option></select></label><label class="field">${t('nameAr')}<input name="الاسم العربي" required></label><label class="field">${t('nameEn')}<input name="الاسم الإنجليزي"></label>${phoneGroup()}<label class="field">${t('email')}<input name="البريد" type="email"></label></div><div class="section-heading"><h3>${state.lang==='ar'?'قدرات العمل':'Work capabilities'}</h3><button id="addCapability" class="secondary" type="button">＋ ${state.lang==='ar'?'إضافة بند':'Add item'}</button></div><div id="capabilityRows">${capabilityRow()}</div><button class="primary">${t('add')}</button></form>`}

agreementTable=function(list){if(!list.length)return `<div class="empty">${t('none')}</div>`;return table(list.map(a=>({'الطرف / المشروع':agreementName(a),'البند':a['معرف بند التشطيب'],'نوع التعامل':a['نوع التعامل'],'التسعير':a['طريقة التسعير'],'الكمية المتفق عليها':a['الكمية المتفق عليها'],'الكمية المنفذة':a['الكمية المنفذة'],'الكمية المعتمدة':a['الكمية المعتمدة'],'الكمية المتبقية':a['الكمية المتبقية'],'سعر الوحدة':a['سعر الوحدة'],'القيمة المعدلة':a['القيمة المعدلة'],'الأعمال المعتمدة':a['قيمة الأعمال المعتمدة'],'المدفوع':a['إجمالي المدفوع'],'المستحق حاليًا':a['المستحق حاليًا'],'الحالة':a['الحالة']})))}
agreementPanel=function(){if(!canAction('agreements','view'))return '';const list=state.data.agreements||[],editable=canAction('agreements','edit');return `${canAction('agreements','create')?`<form id="agreementForm" class="panel"><h2>${state.lang==='ar'?'اتفاق مورد أو مقاول':'Supplier / contractor agreement'}</h2><div class="form-grid">${select('partyId',state.lang==='ar'?'المورد أو المقاول':'Supplier or contractor',state.data.parties||[],'معرف الطرف')}${select('projectId',t('project'),state.data.projects||[],'معرف المشروع')}${select('finishItemId',state.lang==='ar'?'بند العمل':'Work item',state.data.finishItems||[],'معرف البند')}<label class="field">${state.lang==='ar'?'نوع التعامل':'Supply type'}<select name="dealingType"><option>مصنعيات</option><option>مشتريات</option><option>شامل</option></select></label><label class="field">${state.lang==='ar'?'طريقة التسعير':'Pricing method'}<select name="pricingMethod"><option value="LUMP_SUM">${state.lang==='ar'?'مقطوعية':'Lump sum'}</option><option value="UNIT_RATE">${state.lang==='ar'?'سعر وحدة × كمية':'Unit rate × quantity'}</option></select></label><label class="field lump-field">${state.lang==='ar'?'قيمة الاتفاق':'Agreement value'}<input name="amount" type="number" min="0" step=".01"></label><label class="field unit-field hidden">${state.lang==='ar'?'الوحدة':'Unit'}<select name="unit"><option>م²</option><option>م ط</option><option>م³</option><option>عدد</option><option>يومية</option><option>كجم</option><option>طن</option><option>خدمة</option></select></label><label class="field unit-field hidden">${state.lang==='ar'?'الكمية المتفق عليها':'Agreed quantity'}<input name="agreedQuantity" type="number" min="0" step=".01"></label><label class="field unit-field hidden">${state.lang==='ar'?'سعر الوحدة':'Unit rate'}<input name="unitRate" type="number" min="0" step=".01"></label><label class="field">${state.lang==='ar'?'تاريخ الاتفاق «اختياري»':'Agreement date (optional)'}<input name="agreementDate" type="date"></label><label class="field field-wide">${state.lang==='ar'?'الوصف «اختياري»':'Description (optional)'}<input name="description"></label><label class="field field-wide">${t('notes')} «${state.lang==='ar'?'اختياري':'optional'}»<textarea name="notes"></textarea></label><label class="field field-wide">${state.lang==='ar'?'مستند الاتفاق «اختياري»':'Agreement document (optional)'}<input name="agreementDocument" type="file" accept="image/jpeg,image/png,image/webp,application/pdf"></label><label class="check-line"><input name="requireApproval" type="checkbox"><span>${state.lang==='ar'?'طلب اعتماد «اختياري»':'Request approval (optional)'}</span></label></div><button class="primary">${t('save')}</button></form>`:''}${editable?`<details class="panel"><summary>${state.lang==='ar'?'تعديل الاتفاق':'Amend agreement'}</summary><form id="agreementAmend"><div class="form-grid"><label class="field">${state.lang==='ar'?'الاتفاق':'Agreement'}<select name="agreementId" required>${agreementOptions(list)}</select></label><label class="field">${state.lang==='ar'?'قيمة التعديل':'Amendment'}<input name="amount" type="number" step=".01" required></label><label class="field">${state.lang==='ar'?'التاريخ «اختياري»':'Date (optional)'}<input name="date" type="date"></label><label class="field field-wide">${state.lang==='ar'?'السبب':'Reason'}<input name="description"></label></div><button class="primary">${t('save')}</button></form></details><details class="panel"><summary>${state.lang==='ar'?'اعتماد الكميات والأعمال':'Certify quantities and work'}</summary><form id="agreementCertify"><div class="form-grid"><label class="field">${state.lang==='ar'?'الاتفاق':'Agreement'}<select name="agreementId" required>${agreementOptions(list)}</select></label><label class="field">${state.lang==='ar'?'الكمية المنفذة':'Executed quantity'}<input name="executedQuantity" type="number" min="0" step=".01"></label><label class="field">${state.lang==='ar'?'الكمية المعتمدة':'Certified quantity'}<input name="certifiedQuantity" type="number" min="0" step=".01"></label><label class="field">${state.lang==='ar'?'قيمة الأعمال المعتمدة «للمقطوعية»':'Certified value (lump sum)'}<input name="certifiedValue" type="number" min="0" step=".01"></label><label class="field field-wide">${t('notes')}<input name="notes"></label></div><button class="primary">${t('save')}</button></form></details>`:''}<div class="panel formal-report"><div class="section-heading"><h2>${state.lang==='ar'?'كشف حساب الموردين والمقاولين':'Vendor statement'}</h2><button id="printAgreements" class="secondary" type="button">PDF / ${state.lang==='ar'?'طباعة':'Print'}</button></div>${agreementTable(list)}</div>`}

function projectClosingPanel(){if(!canAction('projects','edit'))return '';const projects=state.data.projects||[],closings=state.data.projectClosings||[];return `<div class="panel"><h2>${state.lang==='ar'?'إقفال وتسوية مشروع':'Project closing and settlement'}</h2><p class="muted">${state.lang==='ar'?'مسار مستقل عن الحركة اليومية، ويحتاج اعتمادًا قبل الإقفال المالي.':'Separate from daily transactions and requires approval.'}</p><form id="closingPreviewForm"><div class="form-grid">${select('projectId',t('project'),projects,'معرف المشروع')}</div><button class="secondary">${state.lang==='ar'?'مراجعة موقف المشروع':'Review project'}</button></form><div id="closingPreview"></div></div>${closings.length?`<div class="panel"><h2>${state.lang==='ar'?'طلبات الإقفال':'Closing requests'}</h2>${table(closings)}</div>`:''}`}
const masterSmartClosingBase=masterSmart;masterSmart=function(k){const html=masterSmartClosingBase(k);return k==='projects'?html+projectClosingPanel():html}

function closingPreviewHtml(p){const status=p.canClose?'good':(p.missingDocuments||p.potentialDuplicates||p.taxIssues?'blocker':'warning');return `<div class="closing-status ${status}"><div class="grid"><article class="card">${state.lang==='ar'?'رصيد العميل':'Client balance'}<strong>${money(p.clientBalance)}</strong></article><article class="card">${state.lang==='ar'?'مستحق الموردين':'Vendor due'}<strong>${money(p.vendorBalance)}</strong></article><article class="card">${state.lang==='ar'?'مستندات ناقصة':'Missing documents'}<strong>${p.missingDocuments}</strong></article><article class="card">${state.lang==='ar'?'تكرارات محتملة':'Potential duplicates'}<strong>${p.potentialDuplicates}</strong></article><article class="card">${state.lang==='ar'?'مشكلات ضريبية':'Tax issues'}<strong>${p.taxIssues}</strong></article></div><form id="projectClosingRequest"><input type="hidden" name="projectId" value="${esc(p.project['معرف المشروع'])}"><div class="form-grid"><label class="field">${state.lang==='ar'?'قرار التسوية':'Settlement decision'}<select name="settlementType"><option value="NO_SETTLEMENT">${state.lang==='ar'?'لا توجد تسوية':'No settlement'}</option><option value="COLLECT_CLIENT">${state.lang==='ar'?'تحصيل من العميل':'Collect client'}</option><option value="REFUND_CLIENT">${state.lang==='ar'?'رد للعميل':'Refund client'}</option><option value="AGREED_SETTLEMENT">${state.lang==='ar'?'تسوية متفق عليها':'Agreed settlement'}</option><option value="BAD_DEBT">${state.lang==='ar'?'إعدام دين محاسبي — يخضع لمراجعة ضريبية':'Accounting write-off — tax review'}</option><option value="TRANSFER_PROJECT">${state.lang==='ar'?'ترحيل لمشروع آخر':'Transfer to another project'}</option><option value="WARRANTY_WORK">${state.lang==='ar'?'إصلاح/ضمان قبل الإقفال':'Warranty work before closing'}</option><option value="HISTORICAL_CLOSE">${state.lang==='ar'?'إقفال تاريخي معتمد':'Approved historical close'}</option><option value="KEEP_OPEN">${state.lang==='ar'?'إبقاء مفتوحًا':'Keep open'}</option></select></label><label class="field">${state.lang==='ar'?'قيمة التسوية':'Settlement value'}<input name="settlementAmount" type="number" min="0" step=".01"></label><label class="field">${state.lang==='ar'?'تاريخ الإقفال':'Closing date'}<input name="closingDate" type="date"></label><label class="field field-wide">${state.lang==='ar'?'السبب والتوثيق':'Reason and documentation'}<textarea name="reason" required></textarea></label></div><button class="primary">${state.lang==='ar'?'إرسال للموافقة':'Submit for approval'}</button></form></div>`}

const taxFieldsSmartBase=txTaxFields;txTaxFields=function(){return `<label class="check-line field-wide"><input name="taxable" type="checkbox"><span>${state.lang==='ar'?'فاتورة ضريبية — أدخل الإجمالي المدفوع':'Tax invoice — enter gross paid'}</span></label><div class="tax-fields hidden field-wide"><div class="form-grid"><label class="field">${state.lang==='ar'?'نسبة الضريبة %':'Tax rate %'}<input name="taxRate" type="number" value="14" min="0" max="100" step=".01"></label><input name="taxMode" type="hidden" value="INCLUSIVE"><input name="taxDocumentStatus" type="hidden" value="VALID"><label class="field">${state.lang==='ar'?'رقم الفاتورة الضريبية':'Tax invoice number'}<input name="taxInvoiceNumber"></label><label class="field">${state.lang==='ar'?'تاريخ الفاتورة':'Invoice date'}<input name="taxInvoiceDate" type="date"></label><label class="field">${state.lang==='ar'?'مرجع الفاتورة الإلكترونية «اختياري»':'E-invoice reference (optional)'}<input name="eInvoiceReference"></label></div><p class="muted">${state.lang==='ar'?'السيستم يحسب الصافي والضريبة تلقائيًا ويحدد المعالجة المحاسبية؛ لا يطلب من المهندس قرارًا ضريبيًا فنيًا.':'The system calculates net/VAT and determines accounting treatment automatically.'}</p></div>`}

document.addEventListener('click',e=>{if(e.target.id==='addCapability')document.querySelector('#capabilityRows')?.insertAdjacentHTML('beforeend',capabilityRow());if(e.target.classList.contains('remove-capability'))e.target.closest('.capability-row')?.remove()},true);
document.addEventListener('change',e=>{if(e.target.form?.id==='agreementForm'&&e.target.name==='pricingMethod'){const unit=e.target.value==='UNIT_RATE';e.target.form.querySelectorAll('.unit-field').forEach(x=>x.classList.toggle('hidden',!unit));e.target.form.querySelector('.lump-field')?.classList.toggle('hidden',unit)}},true);
document.addEventListener('submit',async e=>{try{if(e.target.id==='smartMaster'&&e.target.dataset.entity==='party'){const f=e.target,p=obj(f);p.capabilities=[...f.querySelectorAll('.capability-row')].map(r=>({finishItemId:r.querySelector('[name=capabilityItem]').value,dealingType:r.querySelector('[name=capabilityType]').value}));f.dataset.capabilities=JSON.stringify(p.capabilities)}if(e.target.id==='closingPreviewForm'){e.preventDefault();e.stopImmediatePropagation();const r=await api('project.closing.preview',{projectId:e.target.projectId.value});if(!r.ok)throw new Error(msg(r));document.querySelector('#closingPreview').innerHTML=closingPreviewHtml(r.data)}if(e.target.id==='projectClosingRequest'){e.preventDefault();e.stopImmediatePropagation();await run('project.closing.request',obj(e.target))}}catch(error){fail(error)}},true);

function periodReportPanel(){const r=state.data.periodReport,p=state.data.accountantPackage;return `<div class="panel no-print"><h2>${state.lang==='ar'?'مركز التقارير والطباعة':'Reports and printing center'}</h2><p class="muted">${state.lang==='ar'?'اختر التقرير والفترة فقط؛ يجمع النظام النتائج تلقائيًا من الحركات المرحلة.':'Choose a report and period; posted entries are collected automatically.'}</p><form id="periodReportForm"><div class="form-grid"><label class="field">${state.lang==='ar'?'نوع التقرير':'Report type'}<select name="kind"><option value="EXPENSES">${state.lang==='ar'?'إجمالي المصروفات':'Expenses'}</option><option value="WITHDRAWALS">${state.lang==='ar'?'مسحوبات الشركاء':'Partner withdrawals'}</option><option value="LOANS">${state.lang==='ar'?'السلف والسداد':'Loans and repayments'}</option><option value="PAYROLL">${state.lang==='ar'?'المرتبات':'Payroll'}</option></select></label><label class="field">${state.lang==='ar'?'من تاريخ':'From'}<input name="fromDate" type="date" required></label><label class="field">${state.lang==='ar'?'إلى تاريخ':'To'}<input name="toDate" type="date" required></label>${select('projectId',t('project'),state.data.projects||[],'معرف المشروع')}${select('employeeId',t('employee'),state.data.employees||[],'معرف الموظف')}${select('partyId',state.lang==='ar'?'المورد أو المقاول':'Party',state.data.parties||[],'معرف الطرف')}${select('finishItemId',state.lang==='ar'?'بند المشروع':'Project item',state.data.finishItems||[],'معرف البند')}${select('expenseItemId',state.lang==='ar'?'بند المصروف':'Expense item',state.data.expenseItems||[],'معرف بند المصروف')}</div><div class="actions"><button class="primary">${state.lang==='ar'?'إعداد التقرير':'Build report'}</button><button id="accountantPackage" class="secondary" type="button">${state.lang==='ar'?'حزمة المحاسب القانوني':'Statutory accountant package'}</button><button id="printPeriodReport" class="secondary" type="button">PDF / ${state.lang==='ar'?'طباعة':'Print'}</button></div></form></div>${r?periodReportOutput(r):''}${p?accountantPackageOutput(p):''}`}
function periodReportOutput(r){const titles={EXPENSES:'تقرير المصروفات',WITHDRAWALS:'تقرير مسحوبات الشركاء',LOANS:'تقرير السلف والسداد',PAYROLL:'تقرير المرتبات'},hasNotes=(r.rows||[]).some(x=>String(x.notes||'').trim());return `<div class="formal-report">${reportHeader_(titles[r.kind]||r.kind,`${r.period.from||'—'} — ${r.period.to||'—'}`)}<div class="report-table"><table><thead><tr><th>التاريخ</th><th>النوع</th><th>المشروع</th><th>الموظف/الطرف</th><th>البند</th><th>البيان</th>${hasNotes?'<th>ملاحظات</th>':''}<th>القيمة</th></tr></thead><tbody>${(r.rows||[]).map(x=>`<tr><td>${esc(x.date)}</td><td>${esc(x.type)}</td><td>${esc(x.project||'—')}</td><td>${esc(x.employee||x.party||'—')}</td><td>${esc(x.category||'—')}</td><td>${esc(x.description||'')}</td>${hasNotes?`<td>${esc(x.notes||'—')}</td>`:''}<td>${money(x.amount)}</td></tr>`).join('')}</tbody><tfoot><tr><th colspan="${hasNotes?7:6}">الإجمالي</th><th>${money(r.total)}</th></tr></tfoot></table></div></div>`}
function accountantPackageOutput(p){const s=p.statements||{};return `<div class="formal-report">${reportHeader_(state.lang==='ar'?'حزمة المحاسب القانوني':'Statutory accountant package',`${p.period.from||'—'} — ${p.period.to||'—'}`)}<div class="report-note">${esc(p.noticeAr||'')}</div><div class="grid report-totals"><article class="card">الإيرادات<strong>${money(s.incomeStatement?.revenue)}</strong></article><article class="card">المصروفات<strong>${money(s.incomeStatement?.expenses)}</strong></article><article class="card">صافي الربح<strong>${money(s.incomeStatement?.netProfit)}</strong></article><article class="card">صافي ضريبة القيمة المضافة<strong>${money(s.taxSummary?.netVatPayable)}</strong></article></div><h2>ميزان المراجعة</h2>${table(s.trialBalance||[])}<h2>التدفقات النقدية</h2>${table(s.cashFlow?.monthly||[])}<h2>المستندات الناقصة للمراجعة</h2>${table(p.missingDocuments||[])}</div>`}
