function vendorStatementPanel(){const s=state.data.vendorStatement;return `<div class="panel no-print"><h2>${state.lang==='ar'?'كشف حساب مورد / مقاول':'Supplier / contractor statement'}</h2><form id="vendorStatementForm"><div class="form-grid">${select('partyId',state.lang==='ar'?'المورد أو المقاول':'Supplier or contractor',state.data.parties||[],'معرف الطرف')}${select('projectId',t('project'),state.data.projects||[],'معرف المشروع')}<label class="field">${state.lang==='ar'?'من تاريخ':'From'}<input name="fromDate" type="date"></label><label class="field">${state.lang==='ar'?'إلى تاريخ':'To'}<input name="toDate" type="date"></label></div><div class="actions"><button class="primary">${state.lang==='ar'?'إعداد الكشف':'Build statement'}</button><button id="printVendorStatement" class="secondary" type="button">PDF / ${state.lang==='ar'?'طباعة':'Print'}</button></div></form></div>${s?vendorStatementOutput(s):''}`}
function vendorStatementOutput(s){const t=s.totals||{},p=s.party||{};return `<div class="formal-report">${reportHeader_(state.lang==='ar'?'كشف حساب مورد / مقاول':'Supplier / contractor statement',`${s.period?.from||'—'} — ${s.period?.to||'—'}`)}<h2>${esc(p['الاسم العربي']||p['الاسم الإنجليزي']||'')}</h2><div class="grid report-totals"><article class="card">${state.lang==='ar'?'قيمة الاتفاقات المعدلة':'Adjusted agreements'}<strong>${money(t.adjustedAgreementValue)}</strong></article><article class="card">${state.lang==='ar'?'الأعمال المعتمدة':'Certified work'}<strong>${money(t.certifiedWork)}</strong></article><article class="card">${state.lang==='ar'?'المدفوع':'Payments'}<strong>${money(t.payments)}</strong></article><article class="card">${state.lang==='ar'?'المستحق':'Due'}<strong>${money(t.due)}</strong></article></div><h2>${state.lang==='ar'?'الاتفاقات':'Agreements'}</h2>${table(s.agreements||[])}<h2>${state.lang==='ar'?'الحركات والدفعات':'Transactions and payments'}</h2>${table(s.rows||[])}</div>`}
