function categoryManagementPanel(){if(!canAction('settings','create'))return '';const finish=state.data.finishItems||[],expense=state.data.expenseItems||[];return `<div class="panel"><h2>${state.lang==='ar'?'إدارة شجرة البنود':'Category tree management'}</h2><p class="muted">${state.lang==='ar'?'الإضافة أو التعديل هنا يظهر تلقائيًا في الحركة اليومية والموردين والتقارير. أوقف البند بدل حذفه حتى يظل التاريخ سليمًا.':'Additions and edits propagate to transactions, vendors and reports. Disable rather than delete to preserve history.'}</p><form id="categoryForm"><input name="recordId" type="hidden"><input name="version" type="hidden"><div class="form-grid"><label class="field">${state.lang==='ar'?'نوع الشجرة':'Tree'}<select name="tree"><option value="finishItem">${state.lang==='ar'?'بنود المشروعات':'Project items'}</option><option value="expenseItem">${state.lang==='ar'?'مصروفات الشركة والمشروع':'Company/project expenses'}</option></select></label><label class="field">${state.lang==='ar'?'تعديل بند موجود «اختياري»':'Edit existing (optional)'}<select name="existing"><option value=""></option>${finish.map(x=>`<option value="finishItem|${esc(x['معرف البند'])}">${esc(x['المجموعة الرئيسية'])} ← ${esc(x['الاسم العربي'])}</option>`).join('')}${expense.map(x=>`<option value="expenseItem|${esc(x['معرف بند المصروف'])}">${esc(x['المجموعة الرئيسية'])} ← ${esc(x['البند الفرعي'])}</option>`).join('')}</select></label><label class="field">${state.lang==='ar'?'المجموعة الرئيسية':'Main group'}<input name="mainGroup" required></label><label class="field">${state.lang==='ar'?'اسم البند':'Item name'}<input name="itemName" required></label><label class="field finish-category">${state.lang==='ar'?'طبيعة التكلفة':'Cost nature'}<select name="costNature"><option>مصنعيات</option><option>مشتريات</option><option>شامل</option><option>خدمة</option></select></label><label class="field expense-category hidden">${state.lang==='ar'?'النطاق':'Scope'}<select name="scope"><option value="PROJECT">مشروع</option><option value="COMPANY">شركة</option><option value="BOTH">الاثنان</option></select></label><label class="check-line"><input name="active" type="checkbox" checked><span>${state.lang==='ar'?'نشط':'Active'}</span></label></div><button class="primary">${t('save')}</button></form></div>`}
