approvals=function(){const rows=state.data.tasks||[];const cards=rows.map(x=>`<article class="panel approval-card"><div class="section-heading"><h2>${esc(approvalValue_(x,'الوحدة'))} — ${esc(approvalValue_(x,'نوع الإجراء'))}</h2><span class="report-code">${esc(approvalValue_(x,'الأولوية'))}</span></div><div class="approval-facts"><span><b>${state.lang==='ar'?'المنشئ':'Creator'}:</b> ${esc(approvalValue_(x,'منشئ الطلب'))}</span><span><b>${state.lang==='ar'?'التاريخ':'Date'}:</b> ${esc(approvalValue_(x,'أنشئ في'))}</span><span><b>${state.lang==='ar'?'المبلغ':'Amount'}:</b> ${money(approvalValue_(x,'المبلغ',0))}</span><span><b>${state.lang==='ar'?'معرف السجل':'Record ID'}:</b> ${esc(approvalValue_(x,'معرف السجل'))}</span></div><p><b>${state.lang==='ar'?'السبب والتفاصيل':'Reason and details'}:</b> ${esc(approvalValue_(x,'السبب'))}</p><div class="actions"><button class="primary decision" data-id="${esc(x['معرف الموافقة'])}" data-value="APPROVE">${t('approve')}</button><button class="secondary decision" data-id="${esc(x['معرف الموافقة'])}" data-value="REQUEST_CHANGES">${state.lang==='ar'?'طلب استكمال/تصحيح':'Request changes'}</button><button class="secondary decision" data-id="${esc(x['معرف الموافقة'])}" data-value="REJECT">${t('reject')}</button></div></article>`).join('');return `<h1>${t('tasks')}</h1>${cards||`<div class="panel empty">${t('none')}</div>`}${notificationCards()}`};
approvals=function(){const rows=state.data.tasks||[];const cards=rows.map(x=>`<article class="panel approval-card"><div class="section-heading"><h2>${esc(approvalValue_(x,'الوحدة'))} — ${esc(approvalValue_(x,'نوع الإجراء'))}</h2><span class="report-code">${esc(approvalValue_(x,'الأولوية'))}</span></div><div class="approval-facts"><span><b>${state.lang==='ar'?'المنشئ':'Creator'}:</b> ${esc(approvalValue_(x,'المنشئ',approvalValue_(x,'منشئ الطلب')))}</span><span><b>${state.lang==='ar'?'التاريخ':'Date'}:</b> ${esc(approvalValue_(x,'تاريخ العملية',approvalValue_(x,'أنشئ في')))}</span><span><b>${state.lang==='ar'?'المشروع':'Project'}:</b> ${esc(approvalValue_(x,'المشروع'))}</span><span><b>${state.lang==='ar'?'الطرف':'Party'}:</b> ${esc(approvalValue_(x,'الطرف'))}</span><span><b>${state.lang==='ar'?'البند':'Item'}:</b> ${esc(approvalValue_(x,'البند'))}</span><span><b>${state.lang==='ar'?'المبلغ':'Amount'}:</b> ${money(approvalValue_(x,'المبلغ',0))}</span></div><p><b>${state.lang==='ar'?'الوصف':'Description'}:</b> ${esc(approvalValue_(x,'الوصف'))}</p><p><b>${state.lang==='ar'?'السبب والتفاصيل':'Reason and details'}:</b> ${esc(approvalValue_(x,'السبب'))}</p>${x['رابط المستند']?`<p><a class="secondary" href="${esc(x['رابط المستند'])}" target="_blank" rel="noopener">${state.lang==='ar'?'عرض المستند':'View document'}</a></p>`:''}<div class="actions"><button class="primary decision" data-id="${esc(x['معرف الموافقة'])}" data-value="APPROVE">${t('approve')}</button><button class="secondary decision" data-id="${esc(x['معرف الموافقة'])}" data-value="REQUEST_CHANGES">${state.lang==='ar'?'طلب استكمال/تصحيح':'Request changes'}</button><button class="secondary decision" data-id="${esc(x['معرف الموافقة'])}" data-value="REJECT">${t('reject')}</button></div></article>`).join('');return `<h1>${t('tasks')}</h1>${cards||`<div class="panel empty">${t('none')}</div>`}${notificationCards()}`};
