const employeeFormObserver_=new MutationObserver(()=>{const role=document.querySelector('#employeeForm [name="role"]');if(role&&!role.querySelector('[value="FINANCIAL_MANAGER"]'))role.insertAdjacentHTML('beforeend','<option value="FINANCIAL_MANAGER">مدير مالي — Financial Manager</option>');const job=document.querySelector('#employeeForm [name="الوظيفة"]');if(job){['رئيس مجلس إدارة','شريك / مالك','مدير عام','مدير مالي','محاسب','محاسب موقع','مدير موارد بشرية','مسؤول موارد بشرية','مدير مشروع','مهندس موقع','مهندس معماري','مهندس مدني','مهندس كهرباء','مهندس ميكانيكا','مصمم داخلي','مصمم خارجي','مصمم لاندسكيب','مشتريات','مراقب مخزون','مشرف','فني','عامل','سائق','مندوب','إداري','خدمات معاونة'].forEach(x=>{if(![...job.options].some(o=>o.value===x))job.insertAdjacentHTML('afterbegin',`<option>${x}</option>`)})}});employeeFormObserver_.observe(document.querySelector('#app'),{childList:true,subtree:true});

const txDynamicFieldsPartnerBase_=txDynamicFields;
txDynamicFields=function(type){
  if(!['PARTNER_WITHDRAWAL','PARTNER_DEPOSIT'].includes(type))return txDynamicFieldsPartnerBase_(type);
  const partners=(state.data.employees||[]).filter(employee=>isTrue_(employee['هل شريك']));
  const partner=txSelectSmart('employeeId',state.lang==='ar'?'الشريك':'Partner',partners,'معرف الموظف');
  return `${partner}${txPayment(type==='PARTNER_WITHDRAWAL'?'out':'in')}${txAmountAndTail()}`;
};

function partyCapabilityIds_(partyId){
  if(!partyId)return [];
  const party=(state.data.parties||[]).find(item=>String(item['معرف الطرف'])===String(partyId));
  let capabilities=[];
  try{capabilities=JSON.parse(party?.['قدرات العمل']||'[]')}catch(ignore){capabilities=[]}
  const ids=capabilities.map(item=>item.finishItemId).filter(Boolean);
  (state.data.agreements||[]).filter(item=>String(item['معرف الطرف'])===String(partyId)&&item['الحالة']==='ACTIVE').forEach(item=>{if(item['معرف بند التشطيب'])ids.push(item['معرف بند التشطيب'])});
  return [...new Set(ids.map(String))];
}
const updateSmartTxDependenciesPartyBase_=updateSmartTxDependencies;
updateSmartTxDependencies=function(){
  updateSmartTxDependenciesPartyBase_();
  const form=document.querySelector('#tx');
  if(!form||form.type?.value!=='PROJECT_EXPENSE'||!form.finishItemId)return;
  const selected=form.finishItemId.value,partyId=form.partyId?.value;
  if(!partyId)return;
  const allowed=new Set(partyCapabilityIds_(partyId));
  const items=(state.data.finishItems||[]).filter(item=>allowed.has(String(item['معرف البند'])));
  form.finishItemId.innerHTML=txOptions(items,'معرف البند',selected);
};

function financialPeriodPanel_(){const rows=state.data.financialPeriods||[];if(!canAction('finance','edit'))return rows.length?`<div class="panel"><h2>${state.lang==='ar'?'الفترات المالية':'Financial periods'}</h2>${table(rows)}</div>`:'';return `<div class="panel"><h2>${state.lang==='ar'?'إقفال الفترات المالية':'Financial period closing'}</h2><p class="muted">${state.lang==='ar'?'يمنع النظام الإقفال إذا وجدت حركات غير مراجعة أو قيود غير متوازنة. فك الإقفال متاح فقط للشريك أو المدير المالي.':'Closing is blocked while transactions are unreviewed or journals are unbalanced. Reopening is restricted to partners and the financial manager.'}</p><form id="periodCloseForm"><div class="form-grid"><label class="field">${state.lang==='ar'?'الفترة':'Period'}<input name="period" type="month" required></label><label class="field field-wide">${state.lang==='ar'?'سبب الإقفال':'Closing reason'}<input name="reason" required></label></div><div class="actions"><button class="primary">${state.lang==='ar'?'مراجعة وإقفال الفترة':'Validate and close period'}</button></div></form><form id="periodReopenForm"><div class="form-grid"><label class="field">${state.lang==='ar'?'فك فترة':'Reopen period'}<select name="period" required><option value=""></option>${rows.filter(x=>x['الحالة']==='LOCKED').map(x=>`<option>${esc(x['الفترة'])}</option>`).join('')}</select></label><label class="field field-wide">${state.lang==='ar'?'سبب فك الإقفال':'Reopening reason'}<input name="reason" required></label></div><button class="secondary">${state.lang==='ar'?'فك الإقفال':'Reopen'}</button></form>${table(rows)}</div>`}
const financePeriodBase_=financeSmart;financeSmart=function(){const base=financePeriodBase_().replace(/<label class="field">[^<]*<select name="معرف حساب الأستاذ"[\s\S]*?<\/select><\/label>/,'');return `${base}${financialPeriodPanel_()}`};
document.addEventListener('submit',async e=>{if(!['periodCloseForm','periodReopenForm'].includes(e.target.id))return;e.preventDefault();e.stopImmediatePropagation();try{const action=e.target.id==='periodCloseForm'?'finance.period.close':'finance.period.reopen',r=await api(action,obj(e.target));if(!r.ok)throw new Error(msg(r));const list=await api('finance.periods.list',{});if(!list.ok)throw new Error(msg(list));state.data.financialPeriods=list.data;state.notice={type:'ok',text:state.lang==='ar'?'تم تحديث حالة الفترة المالية.':'Financial period status updated.'};render()}catch(error){fail(error)}},true);
const printPreparedBase_=printPrepared_;printPrepared_=function(){const reports=[...document.querySelectorAll('.formal-report')].filter(x=>x.textContent.trim());if(!reports.length)return printPreparedBase_();const target=reports[reports.length-1];reports.forEach(x=>x.classList.toggle('print-target',x===target));document.body.classList.add('single-report-print');window.print();setTimeout(()=>{document.body.classList.remove('single-report-print');reports.forEach(x=>x.classList.remove('print-target'))},500)};

// Release 4.2: safe master-data editing, client-report privacy controls and complete statements.
state.reportOptions={showSuppliers:false,showInternalNotes:false};
state.masterEdit=null;
function masterIdField_(entity){return {client:'معرف العميل',project:'معرف المشروع',party:'معرف الطرف'}[entity]}
function masterListKey_(entity){return {client:'clients',project:'projects',party:'parties'}[entity]}
function masterEditButtonList_(entity,items){if(!canAction(meta[masterListKey_(entity)]?.module||masterListKey_(entity),'edit'))return '';const idField=masterIdField_(entity);return `<div class="panel"><h2>${state.lang==='ar'?'تعديل البيانات الحالية':'Edit existing records'}</h2><div class="edit-record-list">${items.map(x=>`<button type="button" class="secondary master-edit-open" data-entity="${entity}" data-id="${esc(x[idField])}">${state.lang==='ar'?'تعديل':'Edit'} — ${esc(x['الاسم العربي']||x['الاسم الإنجليزي']||x[idField])}</button>`).join('')}</div></div>`}
function masterEditPicker_(entity,items){if(!canAction(meta[masterListKey_(entity)]?.module||masterListKey_(entity),'edit'))return '';const idField=masterIdField_(entity),title=entity==='client'?(state.lang==='ar'?'اسم العميل':'Client name'):entity==='project'?(state.lang==='ar'?'اسم المشروع':'Project name'):(state.lang==='ar'?'اسم المورد أو المقاول':'Supplier or contractor');return `<div class="panel master-edit-picker"><h2>${state.lang==='ar'?'تعديل سجل موجود':'Edit an existing record'}</h2><label class="field">${title}<select class="master-edit-select" data-entity="${entity}"><option value=""></option>${items.map(x=>{const label=x['الاسم العربي']||x['الاسم الإنجليزي']||x[idField],code=x[entity==='client'?'كود العميل':entity==='project'?'كود المشروع':'كود الطرف']||'';return `<option value="${esc(x[idField])}">${esc(label+(code?' — '+code:''))}</option>`}).join('')}</select></label></div><div class="master-edit-form-host">${state.masterEdit?.entity===entity?masterEditForm_():''}</div>`}
function parseJsonArray_(value){try{const out=JSON.parse(value||'[]');return Array.isArray(out)?out:[]}catch(ignore){return []}}
function selectedOptions_(items,id,value){return `<option value=""></option>${items.map(x=>`<option value="${esc(x[id])}" ${String(x[id])===String(value)?'selected':''}>${esc(state.lang==='ar'?(x['الاسم العربي']||x['الاسم']||x['الاسم الإنجليزي']):(x['الاسم الإنجليزي']||x['الاسم']||x['الاسم العربي']))}</option>`).join('')}`}
function editCapabilityRow_(c={}){return `<div class="capability-row"><label class="field">${state.lang==='ar'?'بند العمل':'Work item'}<select name="capabilityItem">${selectedOptions_(state.data.finishItems||[],'معرف البند',c.finishItemId)}</select></label><label class="field">${state.lang==='ar'?'نوع التعامل':'Supply type'}<select name="capabilityType"><option ${c.dealingType==='مصنعيات'?'selected':''}>مصنعيات</option><option ${c.dealingType==='مشتريات'?'selected':''}>مشتريات</option><option ${c.dealingType==='شامل'?'selected':''}>شامل</option></select></label><button class="secondary remove-capability" type="button">×</button></div>`}
function masterEditForm_(){const edit=state.masterEdit;if(!edit)return '';const items=state.data[masterListKey_(edit.entity)]||[],idField=masterIdField_(edit.entity),x=items.find(r=>String(r[idField])===String(edit.id));if(!x)return '';const common=`<input type="hidden" name="id" value="${esc(x[idField])}"><input type="hidden" name="version" value="${esc(x['الإصدار']||0)}"><label class="field">${t('nameAr')}<input name="الاسم العربي" value="${esc(x['الاسم العربي']||'')}" required></label><label class="field">${t('nameEn')}<input name="الاسم الإنجليزي" value="${esc(x['الاسم الإنجليزي']||'')}"></label>`;let extra='';if(edit.entity==='client')extra=`<label class="field">${t('phone')}<input name="الهاتف" value="${esc(x['الهاتف']||'')}"></label><label class="field">${t('email')}<input name="البريد" type="email" value="${esc(x['البريد']||'')}"></label><label class="field field-wide">${t('address')}<input name="العنوان" value="${esc(x['العنوان']||'')}"></label>`;if(edit.entity==='project'){const taxable=x['المعاملة الضريبية']==='TAXABLE';extra=`<label class="field">${t('client')}<select name="معرف العميل" required>${selectedOptions_(state.data.clients||[],'معرف العميل',x['معرف العميل'])}</select></label><label class="field field-wide">${state.lang==='ar'?'عنوان المشروع':'Project address'}<input name="العنوان" value="${esc(x['العنوان']||'')}"></label><label class="field">${state.lang==='ar'?'نوع المشروع':'Project type'}<input name="نوع المشروع" value="${esc(x['نوع المشروع']||'')}"></label><label class="field">${state.lang==='ar'?'نسبة المشروع %':'Project rate %'}<input name="النسبة العامة" type="number" min="0" max="100" step=".01" value="${esc(Number(x['النسبة العامة']||0)*100)}"></label><label class="field">${state.lang==='ar'?'المعاملة الضريبية':'Tax treatment'}<select name="المعاملة الضريبية"><option value="NON_TAXABLE" ${!taxable?'selected':''}>${state.lang==='ar'?'غير ضريبي':'Non-taxable'}</option><option value="TAXABLE" ${taxable?'selected':''}>${state.lang==='ar'?'ضريبي':'Taxable'}</option></select></label><label class="field">${state.lang==='ar'?'نسبة الضريبة %':'Tax rate %'}<input name="نسبة الضريبة الافتراضية" type="number" min="0" max="100" step=".01" value="${esc(Number(x['نسبة الضريبة الافتراضية']||0)*100)}"></label>`}if(edit.entity==='party'){const caps=parseJsonArray_(x['قدرات العمل']);extra=`<label class="field">${state.lang==='ar'?'النوع':'Type'}<select name="النوع"><option ${x['النوع']==='مورد'?'selected':''}>مورد</option><option ${x['النوع']==='مقاول'?'selected':''}>مقاول</option><option ${x['النوع']==='مورد ومقاول'?'selected':''}>مورد ومقاول</option></select></label><label class="field">${t('phone')}<input name="الهاتف" value="${esc(x['الهاتف']||'')}"></label><label class="field">${t('email')}<input name="البريد" value="${esc(x['البريد']||'')}"></label><div class="field-wide"><div class="section-heading"><h3>${state.lang==='ar'?'قدرات العمل':'Work capabilities'}</h3><button id="addEditCapability" class="secondary" type="button">＋</button></div><div id="editCapabilityRows">${(caps.length?caps:[{}]).map(editCapabilityRow_).join('')}</div></div>`}return `<form id="masterEdit" data-entity="${edit.entity}" class="panel"><div class="section-heading"><h2>${state.lang==='ar'?'تعديل السجل':'Edit record'}</h2><button id="cancelMasterEdit" class="secondary" type="button">${state.lang==='ar'?'إلغاء':'Cancel'}</button></div><div class="form-grid">${common}${extra}<label class="field field-wide">${state.lang==='ar'?'سبب التعديل «يُحفظ في سجل المراجعة»':'Change reason (saved in audit log)'}<input name="reason" required></label></div><button class="primary">${t('save')}</button></form>`}
const masterSmartEditBase_=masterSmart;masterSmart=function(k){const base=masterSmartEditBase_(k),entity=meta[k]?.entity,items=state.data[k]||[];if(!entity)return base;const picker=masterEditPicker_(entity,items);return base.replace('</form>',`</form>${picker}`)};
document.addEventListener('click',e=>{const open=e.target.closest('.master-edit-open');if(open){state.masterEdit={entity:open.dataset.entity,id:open.dataset.id};render();return}if(e.target.id==='cancelMasterEdit'){state.masterEdit=null;const host=e.target.closest('.master-edit-form-host');if(host)host.innerHTML=''}if(e.target.id==='addEditCapability')document.querySelector('#editCapabilityRows')?.insertAdjacentHTML('beforeend',editCapabilityRow_())},true);
document.addEventListener('change',e=>{if(!e.target.classList.contains('master-edit-select')||!e.target.value)return;state.masterEdit={entity:e.target.dataset.entity,id:e.target.value};const host=e.target.closest('.master-edit-picker')?.nextElementSibling;if(host?.classList.contains('master-edit-form-host'))host.innerHTML=masterEditForm_()},true);
document.addEventListener('submit',async e=>{if(e.target.id!=='masterEdit')return;e.preventDefault();e.stopImmediatePropagation();const f=e.target,host=f.closest('.master-edit-form-host');try{const p=obj(f),entity=f.dataset.entity,id=p.id,reason=p.reason;delete p.id;delete p.version;delete p.reason;if(entity==='party')p['قدرات العمل']=[...f.querySelectorAll('.capability-row')].map(r=>({finishItemId:r.querySelector('[name=capabilityItem]').value,dealingType:r.querySelector('[name=capabilityType]').value}));if(entity==='project'){p['النسبة العامة']=Number(p['النسبة العامة']||0)/100;p['نسبة الضريبة الافتراضية']=p['المعاملة الضريبية']==='TAXABLE'?Number(p['نسبة الضريبة الافتراضية']||0)/100:0}const r=await api('master.update',{entity,id,changes:p,reason});if(!r.ok)throw new Error(msg(r));const key=masterListKey_(entity),idField=masterIdField_(entity),index=(state.data[key]||[]).findIndex(x=>String(x[idField])===String(id));if(index>=0)state.data[key][index]=r.data;state.masterEdit=null;if(host)host.innerHTML=`<div class="notice ok">${state.lang==='ar'?'تم حفظ التعديل بنجاح.':'Changes saved successfully.'}</div>`;const select=host?.previousElementSibling?.querySelector('.master-edit-select'),selected=select?.selectedOptions?.[0];if(selected)selected.textContent=(r.data['الاسم العربي']||r.data['الاسم الإنجليزي']||selected.textContent);if(select)select.value=''}catch(error){if(host){let notice=host.querySelector('.master-edit-error');if(!notice){notice=document.createElement('div');notice.className='notice error master-edit-error';host.prepend(notice)}notice.textContent=error.message||String(error)}else alert(error.message||String(error))}},true);

detailTable_=function(r){const rows=r.statement||[],special=r.hasSpecialRates,showParty=!!state.reportOptions.showSuppliers,showNotes=!!state.reportOptions.showInternalNotes,canFix=canAction('transactions','edit');const options=`<div class="panel no-print report-options"><h3>${state.lang==='ar'?'خيارات نسخة التقرير':'Report copy options'}</h3><label class="check-line"><input id="reportShowSuppliers" type="checkbox" ${showParty?'checked':''}><span>${state.lang==='ar'?'إظهار أسماء الموردين/المقاولين «نسخة داخلية فقط»':'Show suppliers/contractors (internal copy only)'}</span></label><label class="check-line"><input id="reportShowNotes" type="checkbox" ${showNotes?'checked':''}><span>${state.lang==='ar'?'إظهار الملاحظات الداخلية':'Show internal notes'}</span></label></div>`;return `${options}<div class="report-table"><table><thead><tr><th>${state.lang==='ar'?'التاريخ':'Date'}</th><th>${state.lang==='ar'?'البند':'Item'}</th><th>${state.lang==='ar'?'الوصف':'Description'}</th>${showParty?`<th>${state.lang==='ar'?'المورد/المقاول':'Supplier/contractor'}</th>`:''}${showNotes?`<th>${state.lang==='ar'?'ملاحظات داخلية':'Internal notes'}</th>`:''}<th>${state.lang==='ar'?'القيمة':'Amount'}</th>${special?`<th>${state.lang==='ar'?'النسبة الخاصة':'Special rate'}</th>`:''}<th>${state.lang==='ar'?'قيمة النسبة':'Markup value'}</th><th>${state.lang==='ar'?'قيمة العميل':'Client value'}</th>${canFix?`<th class="no-print">${state.lang==='ar'?'تصحيح':'Correct'}</th>`:''}</tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.transactionDate||'')}</td><td>${esc(x.finishItem||'')}</td><td>${esc(x.description||'—')}${x.companyBears?`<br><small>${state.lang==='ar'?'على حساب الشركة':'Company account'}</small>`:''}</td>${showParty?`<td>${esc(x.party||'—')}</td>`:''}${showNotes?`<td>${esc(x.notes||'—')}</td>`:''}<td>${x.type==='CUSTOMER_RECEIPT'?money(x.receipt):money(x.amount)}</td>${special?`<td>${['TRANSACTION_OVERRIDE','PROJECT_ITEM'].includes(String(x.rateSource))?(Number(x.rate||0)*100).toFixed(2)+'%':'—'}</td>`:''}<td>${x.companyBears?'0.00':money(x.percentageValue)}</td><td>${x.companyBears?'0.00':money(x.clientValue)}</td>${canFix?`<td class="no-print">${x.type==='PROJECT_EXPENSE'?`<div class="reclassify-control"><select class="reclass-item">${selectedOptions_(state.data.finishItems||[],'معرف البند',x.finishItemId)}</select><select class="reclass-party">${selectedOptions_(state.data.parties||[],'معرف الطرف',x.partyId)}</select><button type="button" class="secondary reclassify-save" data-id="${esc(x.transactionId)}">${state.lang==='ar'?'حفظ التصحيح':'Save correction'}</button></div>`:'—'}</td>`:''}</tr>`).join('')}</tbody></table></div>`};
document.addEventListener('change',e=>{if(e.target.id==='reportShowSuppliers'){state.reportOptions.showSuppliers=e.target.checked;render()}if(e.target.id==='reportShowNotes'){state.reportOptions.showInternalNotes=e.target.checked;render()}},true);
document.addEventListener('click',async e=>{const b=e.target.closest('.reclassify-save');if(!b)return;const box=b.closest('.reclassify-control'),item=box.querySelector('.reclass-item').value,party=box.querySelector('.reclass-party').value;if(!item)return;const reason=prompt(state.lang==='ar'?'سبب التصحيح «إلزامي ويُحفظ في سجل المراجعة»':'Correction reason (required and audited)','');if(!reason?.trim())return;try{await run('transaction.reclassify',{id:b.dataset.id,finishItemId:item,partyId:party,reason});state.loadedAt.reports=0;state.data.projectReport=null;state.notice={type:'ok',text:state.lang==='ar'?'تم تصحيح التصنيف وتسجيله في سجل المراجعة.':'Classification corrected and audited.'};render()}catch(error){fail(error)}},true);

financialStatementsPanel=function(){const f=state.data.financialStatements;return `<div class="panel"><h2>${state.lang==='ar'?'القوائم المالية والتوقعات':'Financial statements and forecast'}</h2><div class="form-grid"><label class="field">${state.lang==='ar'?'من تاريخ':'From'}<input id="financialFrom" type="date"></label><label class="field">${state.lang==='ar'?'إلى تاريخ':'To'}<input id="financialTo" type="date"></label></div><div class="actions"><button id="loadFinancialStatements" class="primary" type="button">${state.lang==='ar'?'إعداد القوائم':'Build statements'}</button><button id="printFinancialStatements" class="secondary" type="button">PDF / ${state.lang==='ar'?'طباعة':'Print'}</button></div></div>${f?`<div class="formal-report"><div class="cards"><div class="card"><b>${state.lang==='ar'?'الإيرادات':'Revenue'}</b><strong>${money(f.incomeStatement.revenue)}</strong></div><div class="card"><b>${state.lang==='ar'?'المصروفات':'Expenses'}</b><strong>${money(f.incomeStatement.expenses)}</strong></div><div class="card"><b>${state.lang==='ar'?'صافي الربح':'Net profit'}</b><strong>${money(f.incomeStatement.netProfit)}</strong></div><div class="card"><b>${state.lang==='ar'?'فرق التوازن':'Balance check'}</b><strong>${money(f.financialPosition.balanceCheck)}</strong></div></div><h2>${state.lang==='ar'?'قائمة المركز المالي':'Statement of financial position'}</h2>${table([f.financialPosition])}<h2>${state.lang==='ar'?'ميزان المراجعة':'Trial balance'}</h2>${table(f.trialBalance||[])}<h2>${state.lang==='ar'?'التدفقات النقدية حسب النشاط':'Cash flow by activity'}</h2>${table(f.cashFlow?.activities||[])}<h2>${state.lang==='ar'?'التدفقات النقدية الشهرية':'Monthly cash flow'}</h2>${table(f.cashFlow?.monthly||[])}<h2>${state.lang==='ar'?'التغير في حقوق الملكية':'Changes in equity'}</h2>${table([f.changesInEquity||{}])}<h2>${state.lang==='ar'?'ملخص ضريبة القيمة المضافة':'VAT summary'}</h2>${table([f.taxSummary||{}])}<h2>${state.lang==='ar'?'توقع السيولة لثلاثة أشهر «تقديري»':'Three-month cash forecast (estimate)'}</h2>${table(f.forecast?.nextThreeMonths||[])}</div>`:''}`};

