document.addEventListener('submit',async e=>{if(e.target.id!=='advancedJournalForm')return;e.preventDefault();e.stopImmediatePropagation();try{const p=obj(e.target);p.currency='EGP';p.idempotencyKey=crypto.randomUUID();p.source='FINANCE_ADVANCED';await run('transaction.createAndSubmit',p)}catch(error){fail(error)}},true);

function accountingDateControls_(){return `<div class="form-grid"><label class="field">${state.lang==='ar'?'من تاريخ':'From'}<input id="accountingFrom" type="date"></label><label class="field">${state.lang==='ar'?'إلى تاريخ':'To'}<input id="accountingTo" type="date"></label><label class="field">${state.lang==='ar'?'الحساب «اختياري لدفتر الأستاذ»':'Account (optional for ledger)'}<select id="accountingAccount"><option value=""></option>${(state.data.ledgerAccounts||[]).map(x=>`<option value="${esc(x['معرف الحساب'])}">${esc(x['كود الحساب'])} — ${esc(state.lang==='ar'?x['الاسم العربي']:x['الاسم الإنجليزي'])}</option>`).join('')}</select></label></div><div class="actions period-presets"><button type="button" class="secondary accounting-period" data-period="MONTH">${state.lang==='ar'?'الشهر الحالي':'Current month'}</button><button type="button" class="secondary accounting-period" data-period="YEAR">${state.lang==='ar'?'السنة الحالية':'Current year'}</button><button type="button" class="secondary accounting-period" data-period="LAST_MONTH">${state.lang==='ar'?'الشهر السابق':'Last month'}</button></div>`}
function accountingReportCenter_(){const report=state.data.accountingReport;return `<div class="panel no-print"><h2>${state.lang==='ar'?'الدفاتر والتقارير المحاسبية التفصيلية':'Detailed accounting books and reports'}</h2><p class="muted">${state.lang==='ar'?'اختر أي مدة أو استخدم شهر/سنة، ثم اطبع التقرير A4. الأرقام تُنشأ من القيود المرحلة فقط.':'Choose any period or a month/year preset, then print A4. Figures come from posted journals only.'}</p>${accountingDateControls_()}<div class="actions"><button id="buildGeneralLedger" type="button" class="primary">${state.lang==='ar'?'دفتر الأستاذ العام':'General ledger'}</button><button id="buildJournalRegister" type="button" class="secondary">${state.lang==='ar'?'دفتر اليومية':'Journal register'}</button><button id="buildDetailedStatements" type="button" class="secondary">${state.lang==='ar'?'القوائم التفصيلية':'Detailed statements'}</button><button id="printAccountingReport" type="button" class="secondary">PDF / ${state.lang==='ar'?'طباعة':'Print'}</button></div></div>${report?accountingReportOutput_(report):''}`}
function accountingReportOutput_(r){const subtitle=`${r.period?.from||'—'} — ${r.period?.to||'—'}`;if(r.kind==='GENERAL_LEDGER')return `<div class="formal-report">${reportHeader_(state.lang==='ar'?'دفتر الأستاذ العام':'General ledger',subtitle)}${(r.reports||[]).map(a=>`<section class="ledger-account"><h2>${esc(a.code)} — ${esc(state.lang==='ar'?a.nameAr:a.nameEn)}</h2><div class="report-party"><span>${state.lang==='ar'?'رصيد أول المدة مدين':'Opening debit'}: ${money(a.openingDebit)}</span><span>${state.lang==='ar'?'رصيد أول المدة دائن':'Opening credit'}: ${money(a.openingCredit)}</span><span>${state.lang==='ar'?'حركة مدين':'Period debit'}: ${money(a.periodDebit)}</span><span>${state.lang==='ar'?'حركة دائن':'Period credit'}: ${money(a.periodCredit)}</span><span>${state.lang==='ar'?'رصيد آخر المدة مدين':'Closing debit'}: ${money(a.endingDebit)}</span><span>${state.lang==='ar'?'رصيد آخر المدة دائن':'Closing credit'}: ${money(a.endingCredit)}</span></div>${table(a.rows||[])}</section>`).join('')}</div>`;if(r.kind==='JOURNAL_REGISTER')return `<div class="formal-report">${reportHeader_(state.lang==='ar'?'دفتر اليومية العامة':'General journal',subtitle)}${table(r.rows||[])}<div class="report-summary"><div><span>${state.lang==='ar'?'إجمالي المدين':'Total debit'}</span><b>${money(r.totals?.debit)}</b></div><div><span>${state.lang==='ar'?'إجمالي الدائن':'Total credit'}</span><b>${money(r.totals?.credit)}</b></div><div class="grand"><span>${state.lang==='ar'?'فرق التوازن':'Balance difference'}</span><b>${money(r.totals?.difference)}</b></div></div></div>`;return `<div class="formal-report">${reportHeader_(state.lang==='ar'?'القوائم المالية التفصيلية':'Detailed financial statements',subtitle)}<h2>${state.lang==='ar'?'قائمة الربح أو الخسارة — تفصيل الحسابات':'Profit or loss — account detail'}</h2>${table(r.incomeStatement?.lines||[])}<div class="report-summary"><div><span>${state.lang==='ar'?'الإيرادات':'Revenue'}</span><b>${money(r.incomeStatement?.revenue)}</b></div><div><span>${state.lang==='ar'?'المصروفات':'Expenses'}</span><b>${money(r.incomeStatement?.expenses)}</b></div><div class="grand"><span>${state.lang==='ar'?'صافي الربح أو الخسارة':'Net profit or loss'}</span><b>${money(r.incomeStatement?.netProfit)}</b></div></div><h2>${state.lang==='ar'?'قائمة المركز المالي — تفصيل الحسابات':'Financial position — account detail'}</h2>${table(r.financialPosition?.lines||[])}<h2>${state.lang==='ar'?'ميزان المراجعة':'Trial balance'}</h2>${table(r.trialBalance||[])}<h2>${state.lang==='ar'?'الأداء الشهري والمقارنة':'Monthly performance and comparison'}</h2>${table(r.monthlyPerformance||[])}<h2>${state.lang==='ar'?'التدفقات النقدية حسب النشاط':'Cash flow by activity'}</h2>${table(r.cashFlow?.activities||[])}<h2>${state.lang==='ar'?'التغير في حقوق الملكية':'Changes in equity'}</h2>${table([r.changesInEquity||{}])}<h2>${state.lang==='ar'?'ملخص ضريبة القيمة المضافة':'VAT summary'}</h2>${table([r.taxSummary||{}])}</div>`}
const financeAccountingBase_=financeSmart;financeSmart=function(){return `${financeAccountingBase_()}${accountingReportCenter_()}`};
function accountingPayload_(){return {fromDate:document.querySelector('#accountingFrom')?.value||'',toDate:document.querySelector('#accountingTo')?.value||'',accountId:document.querySelector('#accountingAccount')?.value||''}}
function setAccountingPeriod_(kind){const now=new Date(),toIso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;let from,to;if(kind==='MONTH'){from=new Date(now.getFullYear(),now.getMonth(),1);to=new Date(now.getFullYear(),now.getMonth()+1,0)}else if(kind==='LAST_MONTH'){from=new Date(now.getFullYear(),now.getMonth()-1,1);to=new Date(now.getFullYear(),now.getMonth(),0)}else{from=new Date(now.getFullYear(),0,1);to=new Date(now.getFullYear(),11,31)}document.querySelector('#accountingFrom').value=toIso(from);document.querySelector('#accountingTo').value=toIso(to)}
document.addEventListener('click',async e=>{try{const preset=e.target.closest('.accounting-period');if(preset){setAccountingPeriod_(preset.dataset.period);return}const actions={buildGeneralLedger:'accounting.generalLedger',buildJournalRegister:'accounting.journalRegister',buildDetailedStatements:'accounting.detailedStatements'};const action=actions[e.target.id];if(action){const r=await api(action,accountingPayload_());if(!r.ok)throw new Error(msg(r));state.data.accountingReport=r.data;render();return}if(e.target.id==='printAccountingReport')printPrepared_()}catch(error){fail(error)}},true);

document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button||!/^print/i.test(button.id||''))return;const busy=beginActionButton_();setTimeout(()=>endActionButton_(busy),700)},true);



